package com.k2fsa.sherpa.onnx.tts.engine

import android.content.Context
import android.util.Log
import org.json.JSONObject

/**
 * Reads the Supertonic language allowlist generated by the project builder
 * from the upstream sherpa-onnx native implementation.
 */
object SupertonicLanguageManifest {
    private const val TAG = "SupertonicLanguageManifest"
    private const val ASSET_NAME = "supertonic_languages.json"
    private const val AUTOMATIC_LANGUAGE = "na"

    @Volatile
    private var cachedLanguages: List<String>? = null

    fun languages(context: Context): List<String> {
        cachedLanguages?.let { return it }

        synchronized(this) {
            cachedLanguages?.let { return it }

            val parsed = try {
                val json = context.applicationContext.assets
                    .open(ASSET_NAME)
                    .bufferedReader(Charsets.UTF_8)
                    .use { it.readText() }

                val root = JSONObject(json)
                val array = root.getJSONArray("languages")
                buildList {
                    for (index in 0 until array.length()) {
                        val code = array.getString(index).trim().lowercase()
                        if (code.matches(Regex("[a-z]{2,3}")) && code !in this) {
                            add(code)
                        }
                    }
                }
            } catch (exception: Exception) {
                Log.e(TAG, "Unable to load $ASSET_NAME", exception)
                emptyList()
            }

            cachedLanguages = parsed
            return parsed
        }
    }

    fun localeLanguages(context: Context): List<String> =
        languages(context).filterNot { it == AUTOMATIC_LANGUAGE }

    fun isSupported(context: Context, language: String): Boolean =
        language.lowercase() in languages(context)

    fun isSelectable(context: Context, language: String): Boolean =
        language.lowercase() in localeLanguages(context)
}
